impl Solution {
    pub fn smallest_divisor(nums: Vec<i32>, threshold: i32) -> i32 {
        let mut left = 1;
        let mut right = *nums.iter().max().unwrap();
        let mut ans = right;

        while left <= right {
            let mid = left + (right - left) / 2;
            let mut sum: i64 = 0;
            for &num in &nums {
                sum += (num as f64 / mid as f64).ceil() as i64;
            }

            if sum <= threshold as i64 {
                ans = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        ans
    }
}

